\newtheorem{lemma}{Lemma}
\begin{document}

\section*{Algorithm Name}
Stochastic Gradient Descent with Fixed Step Size (SGD-FS)

\section*{Mathematical Formulation}
Let $f:\mathbb{R}^{d}\rightarrow\mathbb{R}$ be the population objective
\[
    f(w)=\mathbb{E}_{\xi}[\,\ell(w;\xi)\,],
\]
where $\ell(w;\xi)$ is the loss on a random data point $\xi$.
At iteration $t$ we draw an independent minibatch $\mathcal{B}_{t}$ of size $b$,
compute the stochastic gradient
\[
    g_{t}\;:=\;\frac{1}{b}\sum_{\xi\in\mathcal{B}_{t}}\nabla\ell(w_{t};\xi),
\]
and update the parameters by
\[
    w_{t+1}=w_{t}-\eta\,g_{t},\qquad t=0,1,2,\dots
\]
where $\eta>0$ is a fixed step size.

\section*{Pseudocode}
\begin{algorithm}[H]
\caption{SGD with Fixed Step Size}
\begin{algorithmic}[1]
\State \textbf{Input:} initial point $w_{0}\in\mathbb{R}^{d}$, step size $\eta>0$, minibatch size $b$, max iterations $T$
\For{$t=0$ \textbf{to} $T-1$}
    \State Sample a minibatch $\mathcal{B}_{t}$ of size $b$ independently from the data distribution
    \State Compute stochastic gradient $g_{t}= \frac{1}{b}\sum_{\xi\in\mathcal{B}_{t}}\nabla\ell(w_{t};\xi)$
    \State Update $w_{t+1}= w_{t}-\eta\,g_{t}$
\EndFor
\State \textbf{Output:} $w_{T}$
\end{algorithmic}
\end{algorithm}

\section*{Dry Run Example}
Consider the scalar quadratic $f(w)=(w-3)^{2}$.
\begin{itemize}
    \item Gradient: $\nabla f(w)=2(w-3)$.
    \item Initialise $w_{0}=0$, step size $\eta=0.1$, and assume a minibatch of size $1$ so that $g_{t}=\nabla f(w_{t})$ (no stochasticity).
\end{itemize}
\begin{center}
\begin{tabular}{c|c|c|c}
$t$ & $w_{t}$ & $g_{t}=2(w_{t}-3)$ & $w_{t+1}=w_{t}-\eta g_{t}$\\ \hline
0 & $0$ & $-6$ & $0-0.1(-6)=0.6$ \\
1 & $0.6$ & $2(0.6-3)=-4.8$ & $0.6-0.1(-4.8)=1.08$ \\
2 & $1.08$ & $2(1.08-3)=-3.84$ & $1.08-0.1(-3.84)=1.464$ \\
\end{tabular}
\end{center}
Corresponding objective values $f(w_{t})$ are $9$, $5.76$, $3.696$ respectively, showing monotone decrease.

\section*{Assumptions}
\begin{enumerate}[label=\textbf{A\arabic*.}, leftmargin=*]
    \item \textbf{Strong Convexity.} $f$ is $\mu$‑strongly convex ($\mu>0$):
    \[
        f(v)\ge f(w)+\langle\nabla f(w),v-w\rangle+\frac{\mu}{2}\|v-w\|^{2},
        \quad\forall w,v\in\mathbb{R}^{d}.
    \]
    \item \textbf{Smoothness.} $f$ has $L$‑Lipschitz gradient ($L>0$):
    \[
        \|\nabla f(v)-\nabla f(w)\|\le L\|v-w\|,
        \quad\forall w,v\in\mathbb{R}^{d}.
    \]
    \item \textbf{Unbiased Stochastic Gradient.}
    \[
        \mathbb{E}[\,g_{t}\mid w_{t}\,]=\nabla f(w_{t}).
    \]
    \item \textbf{Bounded Variance.} There exists $\sigma^{2}\ge0$ such that
    \[
        \mathbb{E}\big[\|g_{t}-\nabla f(w_{t})\|^{2}\mid w_{t}\big]\le\sigma^{2},
        \qquad\forall t.
    \]
    \item \textbf{Step Size.} The fixed step size satisfies
    \[
        0<\eta<\frac{2}{\mu+L}.
    \]
\end{enumerate}

\section*{Main Convergence Theorem}
\begin{theorem}
\label{thm:linear}
Under Assumptions A1–A5, the iterates of SGD‑FS satisfy for all $t\ge0$
\[
\mathbb{E}\big[\|w_{t}-w^{*}\|^{2}\big]\le
\big(1-\eta\mu\big)^{t}\|w_{0}-w^{*}\|^{2}
\;+\;
\frac{\eta\sigma^{2}}{\mu},
\tag{1}
\]
where $w^{*}=\arg\min f(w)$.
Consequently,
\[
\mathbb{E}\big[f(w_{t})-f(w^{*})\big]\le
\frac{L}{2}\big(1-\eta\mu\big)^{t}\|w_{0}-w^{*}\|^{2}
\;+\;
\frac{\eta L\sigma^{2}}{2\mu}.
\tag{2}
\]
\end{theorem}

\section*{Theoretical Properties}
\begin{enumerate}[label=\textbf{P\arabic*.}, leftmargin=*]
    \item \textbf{Linear (Geometric) Convergence.} The term $(1-\eta\mu)^{t}$ yields an exponential decay provided $\eta\mu\in(0,1)$.
    \item \textbf{Steady‑State Error.} The constant $\frac{\eta\sigma^{2}}{\mu}$ is the asymptotic variance‑induced error; smaller $\eta$ reduces this bias at the cost of slower decay.
    \item \textbf{Comparison to Deterministic GD.} When $\sigma^{2}=0$ the bound reduces to the classic GD rate $\|w_{t}-w^{*}\|^{2}\le (1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}$.
    \item \textbf{Hyperparameter Sensitivity.} The admissible interval for $\eta$ is $(0,2/(\mu+L))$; choosing $\eta$ close to $1/L$ balances speed and variance amplification.
\end{enumerate}

\section*{Discussion}
The theorem shows that even with stochastic minibatch gradients, a constant step size yields a linear convergence to a neighbourhood of the optimum whose radius scales linearly with $\eta$ and the gradient noise level $\sigma^{2}$. This mirrors classical results for strongly convex stochastic optimization and quantifies precisely how step‑size selection trades off speed versus accuracy.

\section*{Preliminaries (Definitions and Lemmas)}
\begin{lemma}[Quadratic Bounds]\label{lem:quad}
For a $\mu$‑strongly convex and $L$‑smooth function $f$,
\[
    2\mu\big(f(w)-f(w^{*})\big)\le\|\nabla f(w)\|^{2}\le 2L\big(f(w)-f(w^{*})\big),
    \qquad\forall w.
\tag{L1}
\]
\end{lemma}
\begin{proof}
The left inequality follows from strong convexity and the right from smoothness; see standard convex analysis. \qedhere
\end{proof}

\begin{lemma}[One‑step Recursion]\label{lem:rec}
For any $w\in\mathbb{R}^{d}$ and any stochastic gradient $g$ with $\mathbb{E}[g]=\nabla f(w)$,
\[
\mathbb{E}\big[\|w-\eta g-w^{*}\|^{2}\big]
=
\|w-w^{*}\|^{2}
-2\eta\langle\nabla f(w),w-w^{*}\rangle
+\eta^{2}\big(\|\nabla f(w)\|^{2}+\mathbb{E}\|g-\nabla f(w)\|^{2}\big).
\tag{L2}
\]
\end{lemma}
\begin{proof}
Expand the squared norm, take conditional expectation and use unbiasedness. \qedhere
\end{proof}

\section*{Main Proof (Step‑by‑Step Derivation)}
We prove Theorem~\ref{thm:linear} by induction on $t$.

\noindent\textbf{Step 1.} Start from the update rule $w_{t+1}=w_{t}-\eta g_{t}$ and apply Lemma~\ref{lem:rec} conditioned on $w_{t}$:
\begin{align}
\mathbb{E}\big[\|w_{t+1}-w^{*}\|^{2}\mid w_{t}\big]
&=
\|w_{t}-w^{*}\|^{2}
-2\eta\langle\nabla f(w_{t}),w_{t}-w^{*}\rangle
+\eta^{2}\Big(\|\nabla f(w_{t})\|^{2}+\mathbb{E}\big[\|g_{t}-\nabla f(w_{t})\|^{2}\mid w_{t}\big]\Big).\nonumber\\
&\stackrel{\text{[Step 1]}}{=}
\|w_{t}-w^{*}\|^{2}
-2\eta\langle\nabla f(w_{t}),w_{t}-w^{*}\rangle
+\eta^{2}\|\nabla f(w_{t})\|^{2}
+\eta^{2}\mathbb{E}\big[\|g_{t}-\nabla f(w_{t})\|^{2}\mid w_{t}\big].
\tag{3}
\end{align}

\noindent\textbf{Step 2.} Use strong convexity (A1) to lower‑bound the inner product:
\[
\langle\nabla f(w_{t}),w_{t}-w^{*}\rangle\ge
f(w_{t})-f(w^{*})+\frac{\mu}{2}\|w_{t}-w^{*}\|^{2}.
\tag{4}
\]
Insert (4) into (3):
\begin{align}
\mathbb{E}\big[\|w_{t+1}-w^{*}\|^{2}\mid w_{t}\big]
&\le
\|w_{t}-w^{*}\|^{2}
-2\eta\Big(f(w_{t})-f(w^{*})\Big)
-\eta\mu\|w_{t}-w^{*}\|^{2}
+\eta^{2}\|\nabla f(w_{t})\|^{2}
+\eta^{2}\sigma^{2},
\tag{5}
\end{align}
where we used the variance bound (A4) in the last term.

\noindent\textbf{Step 3.} Apply the smoothness inequality (Lemma~\ref{lem:quad}, right side) to replace $\|\nabla f(w_{t})\|^{2}$:
\[
\|\nabla f(w_{t})\|^{2}\le 2L\big(f(w_{t})-f(w^{*})\big).
\tag{6}
\]
Plug (6) into (5):
\begin{align}
\mathbb{E}\big[\|w_{t+1}-w^{*}\|^{2}\mid w_{t}\big]
&\le
\big(1-\eta\mu\big)\|w_{t}-w^{*}\|^{2}
-2\eta\big(1-\eta L\big)\big(f(w_{t})-f(w^{*})\big)
+\eta^{2}\sigma^{2}.
\tag{7}
\end{align}

\noindent\textbf{Step 4.} By the step‑size condition $\eta<2/(\mu+L)$ we have $0<\eta L<1$, thus $1-\eta L>0$.
Discard the non‑negative term $-2\eta(1-\eta L)(f(w_{t})-f(w^{*}))$ to obtain a simpler recursion:
\begin{align}
\mathbb{E}\big[\|w_{t+1}-w^{*}\|^{2}\mid w_{t}\big]
\le
\big(1-\eta\mu\big)\|w_{t}-w^{*}\|^{2}
+\eta^{2}\sigma^{2}.
\tag{8}
\end{align}

\noindent\textbf{Step 5.} Take total expectation on both sides of (8):
\begin{align}
\mathbb{E}\big[\|w_{t+1}-w^{*}\|^{2}\big]
\le
\big(1-\eta\mu\big)\mathbb{E}\big[\|w_{t}-w^{*}\|^{2}\big]
+\eta^{2}\sigma^{2}.
\tag{9}
\end{align}
Define $a_{t}:=\mathbb{E}\big[\|w_{t}-w^{*}\|^{2}\big]$.
Then (9) is a linear difference inequality:
\[
a_{t+1}\le (1-\eta\mu)a_{t}+\eta^{2}\sigma^{2}.
\tag{10}
\]

\noindent\textbf{Step 6.} Solve recursion (10) by unrolling:
\begin{align}
a_{t}
&\le (1-\eta\mu)^{t}a_{0}
+\eta^{2}\sigma^{2}\sum_{k=0}^{t-1}(1-\eta\mu)^{k}\nonumber\\
&= (1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}
+\eta^{2}\sigma^{2}\frac{1-(1-\eta\mu)^{t}}{\eta\mu}\nonumber\\
&\le (1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}
+\frac{\eta\sigma^{2}}{\mu}.
\tag{11}
\end{align}
Equation (11) is exactly the bound (1) of Theorem~\ref{thm:linear}. \hfill $\square$

\section*{Rate Derivation (With Constants)}
From Lemma~\ref{lem:quad} (left side) we have
\[
f(w_{t})-f(w^{*})\le\frac{1}{2\mu}\|\nabla f(w_{t})\|^{2}.
\tag{12}
\]
Applying smoothness again,
\[
\|\nabla f(w_{t})\|^{2}\le L^{2}\|w_{t}-w^{*}\|^{2}.
\tag{13}
\]
Taking expectations and using bound (1):
\[
\mathbb{E}[f(w_{t})-f(w^{*})]
\le\frac{L^{2}}{2\mu}
\Big((1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}
+\frac{\eta\sigma^{2}}{\mu}\Big)
=
\frac{L}{2}(1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}
+\frac{\eta L\sigma^{2}}{2\mu},
\]
which is precisely (2).

\section*{Special Cases}
\begin{itemize}
    \item \textbf{Zero variance ($\sigma^{2}=0$).} The bound reduces to
    $\mathbb{E}\|w_{t}-w^{*}\|^{2}\le(1-\eta\mu)^{t}\|w_{0}-w^{*}\|^{2}$,
    i.e., deterministic gradient descent with linear convergence.
    \item \textbf{Vanishing step size.} Let $\eta\downarrow0$ while keeping $\eta\mu$ fixed; the steady‑state error $\frac{\eta\sigma^{2}}{\mu}$ can be made arbitrarily small at the cost of slower decay.
    \item \textbf{Optimal constant step size.} Minimising the RHS of (1) w.r.t. $\eta$ yields $\eta^{\star}= \min\big\{\frac{1}{L},\frac{2}{\mu+L}\big\}$, which recovers the classical optimal step size for strongly convex SGD.
\end{itemize}

